@triton.jit
def renorm_kernel_hold(
    X,
    Out,
    D,
    pre,
    inner,
    s_lead,
    s_dim,
    s_trail,
    maxnorm,
    p,
    BP: tl.constexpr,
    BQ: tl.constexpr,
    IS_P2: tl.constexpr,
):
    # One program owns one sub-tensor (one dim index d), reduces over
    # pre * inner = numel / D elements, and writes every element back scaled.
    d = tl.program_id(0)
    p_idx = tl.arange(0, BP)[:, None]
    q_idx = tl.arange(0, BQ)[None, :]
    mask = (p_idx < pre) & (q_idx < inner)
    off = p_idx * s_lead + d * s_dim + q_idx * s_trail

    x = tl.load(X + off, mask=mask, other=0.0)
    xf = x.to(tl.float32)

    if IS_P2:
        acc = tl.sum(xf * xf)
    else:
        ax = tl.abs(xf)
        acc = tl.sum(tl.where(ax > 0.0, tl.exp(p * tl.log(ax)), 0.0))

    if IS_P2:
        norm = tl.sqrt(acc)
    else:
        norm = tl.where(acc > 0.0, tl.exp(tl.log(acc) / p), 0.0)

    scale = tl.where(norm > maxnorm, maxnorm / norm, 1.0)
    out = (xf * scale).to(x.dtype)
    tl.store(Out + off, out, mask=mask)


