        p_idx = p0 + tl.arange(0, BP)
        for q0 in range(0, inner, BQ):
            q_idx = q0 + tl.arange(0, BQ)
            mask = (p_idx[:, None] < pre) & (q_idx[None, :] < inner)
            off = p_idx[:, None] * s_lead + d * s_dim + q_idx[None, :] * s_trail
