@triton.jit
def renorm_kernel_lastaxis(
    X,
    Out,
    D,
    pre,
    maxnorm,
    p,
    BP: tl.constexpr,
    DB: tl.constexpr,
    IS_P2: tl.constexpr,
):
    # inner == 1 case (dim == last on contiguous input): sub-tensor for column d
    # is X[p, d] at flat offset p*D + d. A (BP, DB) tile is coalesced along the
    # d axis; the reduction runs over the p axis (axis 0).
    pid = tl.program_id(0)
    d = pid * DB + tl.arange(0, DB)  # (DB,)
    p_idx = tl.arange(0, BP)[:, None]  # (BP, 1)
    mask = (p_idx < pre) & (d[None, :] < D)
    off = p_idx * D + d[None, :]

    x = tl.load(X + off, mask=mask, other=0.0)
    xf = x.to(tl.float32)

    if IS_P2:
        acc = tl.sum(xf * xf, axis=0)
    else:
        ax = tl.abs(xf)
        acc = tl.sum(tl.where(ax > 0.0, tl.exp(p * tl.log(ax)), 0.0), axis=0)

    if IS_P2:
        norm = tl.sqrt(acc)
    else:
        norm = tl.where(acc > 0.0, tl.exp(tl.log(acc) / p), 0.0)

    scale = tl.where(norm > maxnorm, maxnorm / norm, 1.0)
    out = (xf * scale[None, :]).to(x.dtype)
    tl.store(Out + off, out, mask=mask)


def _next_pow2(n):
    p = 1
    while p < n:
        p *= 2
    return p


MAX_TILE = 8192
CHUNK_P = 64
CHUNK_Q = 64
LASTAXIS_DB = 32


def renorm(input, p, dim, maxnorm):
    x = input
    ndim = x.dim()
    dim_n = int(dim) % ndim

    out = torch.empty_like(x)
    if x.numel() == 0:
        return out

    shape = x.shape
    pre = 1
    for i in range(dim_n):
        pre *= shape[i]
    D = shape[dim_n]
    inner = 1
    for i in range(dim_n + 1, ndim):
        inner *= shape[i]

    # Contiguous [pre, D, inner] decomposition: for a fixed d the sub-tensor is
    # X[p, d, q] at flat offset p*(D*inner) + d*inner + q, with p in [0, pre)
    # and q in [0, inner). This is exact for any contiguous input of any ndim.
    s_lead = D * inner
    s_dim = inner
    s_trail = 1

    p_f = float(p)
    maxnorm_f = float(maxnorm)
    IS_P2 = p_f == 2.0

    BP = _next_pow2(pre)
    BQ = _next_pow2(inner)

    if inner == 1:
        DB = LASTAXIS_DB
        BP = _next_pow2(pre)
        renorm_kernel_lastaxis[(triton.cdiv(D, DB),)](
            x,
            out,
            D,
            pre,
            maxnorm_f,
            p_f,
            BP=BP,
            DB=DB,
            IS_P2=IS_P2,
        )
    elif BP * BQ <= MAX_TILE:
        if D >= 32 and D % 2 == 0:
            renorm_kernel_hold_dblk[(D // 2,)](
                x,
                out,
                D,
                pre,
                inner,
                s_lead,
                s_dim,
                s_trail,
                maxnorm_f,
                p_f,
                BP=BP,
                BQ=BQ,
                DB=2,
                IS_P2=IS_P2,
            )
        else:
            renorm_kernel_hold[(D,)](
                x,
                out,
                D,
                pre,
                inner,
                s_lead,
                s_dim,
                s_trail,
                maxnorm_f,
                p_f,
                BP=BP,
                BQ=BQ,
                IS_P2=IS_P2,
            )
    else:
        renorm_kernel_chunked[(D,)](
            x,
            out,
            D,
            pre,
            inner,
            s_lead,
            s_dim,
            s_trail,
            maxnorm_f,
            p_f,
            BP=CHUNK_P,
            BQ=CHUNK_Q,
            IS_P2=IS_P2,
        )

    return out
